#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, x, y, c;
    cin >> n >> x >> y >> c;

    const int64 top = x - 1;
    const int64 bottom = n - x;
    const int64 left = y - 1;
    const int64 right = n - y;

    auto colored = [&](int64 r) -> i128 {
        i128 total = 1 + 2 * (i128)r * (r + 1);

        auto subtractSide = [&](int64 distance) {
            if (r > distance) {
                i128 excess = r - distance;
                total -= excess * excess;
            }
        };

        subtractSide(top);
        subtractSide(bottom);
        subtractSide(left);
        subtractSide(right);

        auto addCorner = [&](int64 a, int64 b) {
            int64 excess = r - a - b;
            if (excess > 1)
                total += (i128)excess * (excess - 1) / 2;
        };

        addCorner(top, left);
        addCorner(top, right);
        addCorner(bottom, left);
        addCorner(bottom, right);

        return total;
    };

    int64 low = 0, high = 2 * (n - 1);
    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (colored(mid) >= (i128)c)
            high = mid;
        else
            low = mid + 1;
    }

    cout << low;
    return 0;
}

